// Plays the in-app notification sound (a soft two-note glassy chime) for
// non-chat notifications — votes, comments, replies, job applications. Chat
// messages keep their own boxing-bell ding (features/chat/utils/notification-sound).
// The asset lives at public/sounds/notification.mp3 and is generated by
// scripts/gen-notification-sound.mjs.

const SRC = '/sounds/notification.mp3';
// Don't let a burst of incoming notifications stack overlapping chimes.
const MIN_GAP_MS = 800;

let audio: HTMLAudioElement | null = null;
let lastPlayedAt = 0;

const getAudio = (): HTMLAudioElement | null => {
    if (typeof window === 'undefined') return null;
    if (!audio) {
        audio = new Audio(SRC);
        audio.preload = 'auto';
        audio.volume = 0.5;
    }
    return audio;
};

/** Play the alert for an incoming notification. No-op on the server, when
 *  throttled, or when the browser blocks autoplay (rejected play() swallowed). */
export const playNotificationSound = (): void => {
    const el = getAudio();
    if (!el) return;

    const now = Date.now();
    if (now - lastPlayedAt < MIN_GAP_MS) return;
    lastPlayedAt = now;

    try {
        el.currentTime = 0;
        void el.play().catch(() => {
            /* Autoplay can be blocked until the user interacts — ignore. */
        });
    } catch {
        /* Older Safari can throw synchronously on currentTime — ignore. */
    }
};
